const raw = $input.first().json;

// Handle all possible webhook payload structures
const data = raw.body || raw.data || raw;

// Extract all fields with fallbacks
const listing = {
  listingAddress:  data.listingAddress  || data.address        || null,
  listingPrice:    parseFloat(data.listingPrice || data.price  || 0),
  bedrooms:        data.bedrooms        || data.beds            || null,
  bathrooms:       data.bathrooms       || data.baths           || null,
  sqft:            data.sqft            || data.squareFeet      || null,
  propertyType:    data.propertyType    || data.type            || null,
  neighborhood:    data.neighborhood    || data.area            || null,
  zipCode:         data.zipCode         || data.zip             || null,
  description:     data.description     || data.details         || null,
  listingUrl:      data.listingUrl      || data.url             || null,
  daysOnMarket:    parseInt(data.daysOnMarket || data.days || 0),
  source:          data.source          || 'Manual',

  // Agent + workflow config
  CALENDLY_USERNAME:  data.CALENDLY_USERNAME  || 'qualmatic',
  CALENDLY_EVENT_SLUG: data.CALENDLY_EVENT_SLUG || 'property-viewing',
  AGENT_EMAIL:        data.AGENT_EMAIL         || 'user@example.com',
  AGENT_NAME:         data.AGENT_NAME          || 'QM',
  MAX_MATCHES:        parseInt(data.MAX_MATCHES || '5'),
  DAYS_SINCE_CONTACT: parseInt(data.DAYS_SINCE_CONTACT || '14'),
  BUDGET_FLEXIBILITY: 0.10  // 10% over budget still qualifies — adjust as needed
};

// Validate required fields
if (!listing.listingAddress) {
  throw new Error('listingAddress is required in the webhook payload');
}
if (!listing.listingPrice || listing.listingPrice === 0) {
  throw new Error('listingPrice is required in the webhook payload');
}

return [{ json: listing }];

const listing = $('Normalize Listing Details').first().json;
const BUDGET_FLEXIBILITY = parseFloat($('Normalize Listing Details').first().json.BUDGET_FLEXIBILITY || '0.10');
const DAYS_SINCE_CONTACT = parseInt(listing.DAYS_SINCE_CONTACT || '14');

const allLeads = $input.all().map(i => i.json);
const candidates = [];

for (const lead of allLeads) {
  // Must be active
  const isActive = String(lead['Active'] || '').toLowerCase().trim();
  if (isActive !== 'true') continue;

  // Must have email
  const email = (lead['Email'] || '').trim();
  if (!email) continue;

  // Budget check
  const budgetMin = parseFloat(
    String(lead['Budget Min'] || '0').replace(/[^0-9.]/g, '')
  ) || 0;
  const budgetMax = parseFloat(
    String(lead['Budget Max'] || '9999999').replace(/[^0-9.]/g, '')
  ) || 9999999;
  const price = parseFloat(listing.listingPrice) || 0;
  const adjustedMax = budgetMax * (1 + BUDGET_FLEXIBILITY);

  if (price < budgetMin || price > adjustedMax) continue;

  // Property type check
  const leadType = (lead['Property Type'] || 'any').toLowerCase().trim();
  const listingType = (listing.propertyType || '').toLowerCase().trim();
  if (leadType !== 'any' && leadType !== '' && leadType !== listingType) continue;

  // Recently contacted check
  if (lead['Last Contacted']) {
    const lastContact = new Date(lead['Last Contacted']);
    if (!isNaN(lastContact.getTime())) {
      const daysSince = (Date.now() - lastContact.getTime()) / (1000 * 60 * 60 * 24);
      if (daysSince < DAYS_SINCE_CONTACT) continue;
    }
  }

  candidates.push({
    leadId:            lead['leadId']            || lead['Lead ID'] || email,
    leadName:          lead['Lead Name']         || 'there',
    leadEmail:         email,
    leadPhone:         lead['Phone']             || null,
    budgetMin:         lead['Budget Min']        || null,
    budgetMax:         lead['Budget Max']        || null,
    preferredLocation: lead['Preferred Location']|| null,
    propertyType:      lead['Property Type']     || null,
    bedroomsMin:       lead['Bedrooms Min']      || null,
    timeline:          lead['Timeline']          || null,
    notes:             lead['Notes']             || null,
    facebookLeadId:    lead['Facebook Lead ID']  || null
  });
}

return candidates.map(c => ({ json: { ...c, listing } }));

