parameters.jsCode:
// ============================================================
const LISTING_NODE = 'Normalize Listing Details';
const FILTER_NODE = 'Stage 1 Filter: Hard Criteria';
// ============================================================

const listing = $(LISTING_NODE).first().json;
const allCandidates = $(FILTER_NODE).all().map(i => i.json);
const maxMatches = parseInt(listing.MAX_MATCHES || '5');

// Extract Gemini output
const allItems = $input.all();
let rawText = '';
for (const item of allItems) {
  const text = item.json?.content?.parts?.[0]?.text
    || item.json?.candidates?.[0]?.content?.parts?.[0]?.text
    || item.json?.output || '';
  if (text && text.includes('matchScore')) {
    rawText = text;
    break;
  }
}

const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

let scores = [];
try {
  scores = JSON.parse(cleaned);
} catch (e) {
  // Fallback — mark all candidates as Possible Match
  scores = allCandidates.map(c => ({
    leadId: c.leadId,
    leadName: c.leadName,
    matchScore: 'Possible Match',
    matchReason: 'AI scoring unavailable — review manually.',
    email_subject: `A property just listed that might interest you`,
    email_body: `Hi ${c.leadName},\n\nA new property just listed that fits several of your requirements. I wanted to make sure you had a chance to take a look before it moves.`
  }));
}

// HTML email formatter
function escapeHtml(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatEmailHtml(text) {
  if (!text) return '';
  const paragraphs = text
    .split(/\n\s*\n/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  return paragraphs.map(p => `<p>${escapeHtml(p)}</p>`).join('');
}

// Build Calendly booking link
const calendlyUsername = listing.CALENDLY_USERNAME || '';
const calendlySlug = listing.CALENDLY_EVENT_SLUG || 'property-viewing';
const bookingLink = calendlyUsername
  ? `https://calendly.com/${calendlyUsername}/${calendlySlug}`
  : null;

// Merge scores with candidate data
const scoredLeads = scores.map((score, i) => {
  const candidate = allCandidates.find(c => c.leadId === score.leadId)
    || allCandidates[i]
    || {};

  return {
    ...candidate,
    matchScore:   score.matchScore || 'Poor Match',
    matchReason:  score.matchReason || '',
    email_subject: score.email_subject || null,
    email_body:    score.email_body
      ? formatEmailHtml(score.email_body)
      : null,
    bookingLink
  };
});

// Filter to Strong + Possible only, cap at maxMatches
const topMatches = scoredLeads
  .filter(l => l.matchScore === 'Strong Match' || l.matchScore === 'Possible Match')
  .sort((a, b) => {
    // Strong Match first
    if (a.matchScore === 'Strong Match' && b.matchScore !== 'Strong Match') return -1;
    if (b.matchScore === 'Strong Match' && a.matchScore !== 'Strong Match') return 1;
    return 0;
  })
  .slice(0, maxMatches);

const strongCount = topMatches.filter(l => l.matchScore === 'Strong Match').length;
const possibleCount = topMatches.filter(l => l.matchScore === 'Possible Match').length;

// Build agent summary HTML
const agentSummaryHtml = `
  <div style="font-family:Arial,sans-serif;max-width:600px;">
    <div style="background:#1a1a2e;color:white;padding:20px;border-radius:8px 8px 0 0;">
      <h2 style="margin:0;">🏠 Property Match Report</h2>
      <p style="margin:8px 0 0 0;opacity:0.8;">
        ${escapeHtml(listing.listingAddress)}
      </p>
    </div>
    <div style="background:#f8f9fa;padding:12px 20px;border-bottom:1px solid #ddd;">
      <p style="margin:0;font-size:14px;">
        <strong>${topMatches.length}</strong> buyers contacted &nbsp;|&nbsp;
        <strong>${strongCount}</strong> Strong Matches &nbsp;|&nbsp;
        <strong>${possibleCount}</strong> Possible Matches
      </p>
    </div>
    <div style="padding:20px;background:white;">
      ${topMatches.map(lead => `
        <div style="border-left:4px solid ${lead.matchScore === 'Strong Match' ? '#27ae60' : '#f39c12'};
          padding:12px 16px;margin:12px 0;border-radius:0 8px 8px 0;background:#f9f9f9;">
          <p style="margin:0 0 4px 0;">
            <strong>${lead.matchScore === 'Strong Match' ? '✅' : '📋'} 
            ${escapeHtml(lead.matchScore)} — ${escapeHtml(lead.leadName)}</strong>
          </p>
          <p style="margin:0 0 4px 0;color:#555;font-size:14px;">
            ${escapeHtml(lead.leadEmail)} | 
            Budget: ${escapeHtml(lead.budgetMin)}–${escapeHtml(lead.budgetMax)}
          </p>
          <p style="margin:0;font-size:14px;">
            <strong>Reason:</strong> ${escapeHtml(lead.matchReason)}
          </p>
          <p style="margin:4px 0 0 0;font-size:13px;color:#27ae60;">
            Match email sent ✅
          </p>
        </div>
      `).join('')}
    </div>
    <div style="padding:16px 20px;background:#f8f9fa;border-top:1px solid #ddd;
      border-radius:0 0 8px 8px;font-size:13px;color:#666;">
      <strong>Listing:</strong> ${escapeHtml(listing.listingAddress)} | 
      $${Number(listing.listingPrice).toLocaleString()} | 
      ${escapeHtml(listing.bedrooms)}bd ${escapeHtml(listing.bathrooms)}ba |
      Day ${escapeHtml(listing.daysOnMarket)} | ${escapeHtml(listing.source)}<br>
      ${listing.listingUrl 
        ? `<a href="${escapeHtml(listing.listingUrl)}" style="color:#3498db;">View listing →</a>`
        : ''}
    </div>
  </div>
`;

// Slack notification
const slackNotification = topMatches.length > 0
  ? `🏠 *${topMatches.length} buyer${topMatches.length > 1 ? 's' : ''} matched — ${listing.listingAddress}*\n` +
    `$${Number(listing.listingPrice).toLocaleString()} | ${listing.bedrooms}bd | Day ${listing.daysOnMarket}\n\n` +
    topMatches.slice(0, 3).map(l =>
      `${l.matchScore === 'Strong Match' ? '✅' : '📋'} *${l.leadName}* — ${l.matchReason}`
    ).join('\n')
  : '';

return [{
  json: {
    topMatches,
    strongCount,
    possibleCount,
    totalContacted: topMatches.length,
    hasMatches: topMatches.length > 0,
    agentSummaryHtml,
    slackNotification,
    listing,
    timestamp: new Date().toISOString()
  }
}];

// Reference Parse AI Output which has the full summary
const summaryData = $('Parse AI Output').first().json;

return [{
  json: {
    agentSummaryHtml: summaryData.agentSummaryHtml,
    slackNotification: summaryData.slackNotification,
    totalContacted: summaryData.totalContacted,
    strongCount: summaryData.strongCount,
    possibleCount: summaryData.possibleCount,
    listing: summaryData.listing,
    hasMatches: summaryData.hasMatches
  }
}];

// Collect all candidate items into a single array
const candidates = $input.all().map(item => ({
  leadId:            item.json.leadId,
  leadName:          item.json.leadName,
  leadEmail:         item.json.leadEmail,
  leadPhone:         item.json.leadPhone,
  budgetMin:         item.json.budgetMin,
  budgetMax:         item.json.budgetMax,
  preferredLocation: item.json.preferredLocation,
  propertyType:      item.json.propertyType,
  bedroomsMin:       item.json.bedroomsMin,
  timeline:          item.json.timeline,
  notes:             item.json.notes
}));

const listing = $input.first().json.listing;

// Return single item containing all candidates
return [{
  json: {
    candidates,
    listing,
    candidateCount: candidates.length
  }
}];

